function beginTurn(){initializeArrivals();state.actionsLeft=actionLimit();state.civilianMoved=Array(districts.length).fill(0);spawnCivilians();reinforce();spawnRival();if(state.turn>=state.nextScientistTurn){state.nextScientistTurn=state.turn+arrivalDelay(10,3);const scientist={type:'scientist',pos:randomEdge(),hp:3};equipScientist(scientist);state.enemies.push(scientist);message('Turn '+state.turn+': mad scientist arrives with '+scientist.weapon.name+' ('+weaponText(scientist.weapon)+' damage).');}}

function d6(){return 1+Math.floor(Math.random()*6)}
function weaponParts(w){return {health:w.health??(w.meter==='hp'?w.damage:0),energy:w.energy??(w.meter==='en'?w.damage:0)}}
function weaponText(w){const p=weaponParts(w);return p.health+' health + '+p.energy+' energy';}
function inventWeapon(die){if(die===undefined){die=state.weaponDie||2;state.weaponDie=die+1;state.inventionCount=(state.inventionCount||0)+1;}const damage=1+Math.floor(Math.random()*die),health=Math.floor(Math.random()*(damage+1)),energy=damage-health;const titles=health===0?['Freeze ray','Gravity siphon','Stasis cannon']:energy===0?['Plasma lance','Sonic disruptor','Lightning projector']:['Entropy beam','Quantum destabilizer','Fusion disruptor'];return {name:titles[Math.floor(Math.random()*titles.length)],die,damage,health,energy};}
function equipScientist(e,forceNew=false){state.weapons??=[];if(state.weapons.some(w=>w.damage>=4)&&Math.random()<.5)e.weapon={...state.weapons.reduce((best,w)=>w.damage>best.damage?w:best)};else{e.weapon=inventWeapon();state.weapons.push({...e.weapon});}e.shots=0;e.phase='hunting';}
function scientistAction(e){if((e.flameUntil||0)>state.turn)return;if(e.phase==='offmap'){if(state.turn<e.returnTurn)return;recordMove('scientist',-1,e.exit);e.pos=e.exit;equipScientist(e);message('The scientist returns from the off-map laboratory.');return}if(e.phase==='retreating'){const edge=districts.map((d,i)=>d.edge?i:-1).filter(i=>i>=0);const route=path(e.pos,edge);if(route.length>1)moveUnit(e,route[1]);if(districts[e.pos].edge){e.exit=e.pos;recordMove('scientist',e.pos,-1);e.pos=-1;e.phase='offmap';e.returnTurn=state.turn+arrivalDelay(10,3);message('The scientist flies off the map to replace the weapon.');}return}if(!e.weapon)equipScientist(e);const route=path(e.pos,[state.pos]);if(route.length-1>1){moveUnit(e,route[1]);message('The scientist flies to '+districts[e.pos].name+'.');return}const w=e.weapon,p={...weaponParts(w)};if(state.abilities.includes('Armored hide')){if(p.health>0)p.health--;else if(p.energy>0)p.energy--;}const beforeHealth=state.hp,beforeEnergy=state.en;state.hp=Math.max(0,state.hp-p.health);state.en=Math.max(0,state.en-p.energy);state.attackReports.push({name:w.name,damage:w.damage,health:p.health,energy:p.energy,beforeHealth,beforeEnergy,afterHealth:state.hp,afterEnergy:state.en,place:districts[e.pos].name});message(w.name+' fires: '+weaponText(w)+' damage.');e.shots++;if(e.shots>=3){e.phase='retreating';message('After three shots, the scientist begins flying to the map edge for another weapon.');}}
function scientistsTurn(actions=2){state.attackReports??=[];for(const e of state.enemies.filter(e=>e.type==='scientist'))for(let action=0;action<actions&&state.hp;action++)scientistAction(e);}
function showScientistReport(){const reports=state.attackReports||[];if(!reports.length)return;const r=reports[0],p=weaponParts(r),dialog=$('scienceDialog');$('scienceTitle').textContent=r.name.toUpperCase();$('scienceDamage').textContent='−'+p.health+' HEALTH / −'+p.energy+' ENERGY';const beforeHealth=r.beforeHealth??(r.meter==='hp'?r.before:state.hp),beforeEnergy=r.beforeEnergy??(r.meter==='en'?r.before:state.en),afterHealth=r.afterHealth??(r.meter==='hp'?r.after:state.hp),afterEnergy=r.afterEnergy??(r.meter==='en'?r.after:state.en);$('scienceDetail').textContent='Fired from '+r.place+' · range 1. Health '+beforeHealth+' → '+afterHealth+'; energy '+beforeEnergy+' → '+afterEnergy+'. Total weapon damage: '+r.damage+'. This split is locked for this weapon.';if(!dialog.open)dialog.showModal();}
function dismissReport(){state.attackReports.shift();$('scienceDialog').close();render();}

function endTurn(){cap();if(state.hp>0){phase('Monsters',()=>rivalTurn(1));if(state.hp>0)phase('Monsters · second action',()=>rivalTurn(1));if(state.hp>0)phase('Civilians',()=>{rescueAtTurnStart();if(state.turn%3===0)fleeCivilians()});phase('Police',policeTurn);if(state.hp>0)phase('Military',militaryTurn);if(state.hp>0)phase('Scientists',()=>scientistsTurn(1));if(state.hp>0)phase('Scientists · second action',()=>scientistsTurn(1));phase('City fires',fireTurn);if(state.en===0&&state.hp>0){state.hp--;message('Starvation: −1 health.');}cap();if(state.hp>0){state.turn++;beginTurn();}}if(!state.hp){state.actionsLeft=0;message('The monster has fallen. Tokyo survives this morning.');}render()}
function spendAction(){state.actionsLeft--;cap();if(buildingMotion&&actionStart){motionFrames.push({label:'Your monster',before:actionStart,after:copyState(),moves:motionMoves.slice()});actionStart=null;motionMoves=[];}if(state.hp<20||state.en<20)state.evolved=false;if(state.actionsLeft<=0||state.hp<=0)endTurn();else render();}
function performBerserk(){if(!state.hp||(state.attackReports||[]).length)return;if(!consume()){const targets=[...new Set([...state.food.map((n,i)=>n>0?i:-1).filter(i=>i>=0),...state.enemies.filter(e=>edible(e)||e.type==='kaiju').map(e=>e.pos)])];if(!targets.length){const rivals=state.enemies.filter(e=>e.type==='kaiju');if(rivals.some(e=>e.pos===state.pos))hit(false);else if(rivals.length){let p=path(state.pos,rivals.map(e=>e.pos));if(p?.length>1){recordMove('monster',state.pos,p[1]);state.pos=p[1];walkingDamage();state.en=Math.max(0,state.en-1);message('Berserk: charging toward rival flesh.')}}else message('Berserk: no food remains. The beast searches.')}else{const p=path(state.pos,targets);recordMove('monster',state.pos,p[1]);state.pos=p[1];damageDistrict(10);state.en=Math.max(0,state.en-1);autoFeed();message('Berserk: rushed toward food in '+districts[state.pos].name+'.')}}spendAction()}
function performAction(kind,arg){if(!state.hp||(state.attackReports||[]).length)return;if(state.en<6){performBerserk();return}let done=false;if(kind==='move'&&districts[state.pos].links.includes(arg)){recordMove('monster',state.pos,arg);state.pos=arg;walkingDamage();state.en--;message('Moved to '+districts[arg].name+'. −1 energy.');autoFeed();done=true}if(kind==='feed')done=feedAttack();if(kind==='attack')done=hit(false);if(kind==='special'&&state.en>=2)done=hit(true,arg);if(kind==='heal'&&state.hp<20&&state.en>0){const amount=roundStat(Math.min(4,20-state.hp,state.en));state.hp+=amount;state.en-=amount;message('Healed '+amount+' health for '+amount+' energy.');done=true}if(kind==='wait'){damageDistrict(10);message('The monster uses one action to wait.');done=true}if(done)spendAction()}
function evolve(ability){if(motionBusy)return;if(!availableEvolutions().includes(ability)||state.hp!==20||state.en!==20||state.evolved||state.abilities.includes(ability))return;state.abilities.push(ability);if(ability==='Third action')state.actionsLeft++;state.evolved=true;message('EVOLUTION: '+ability+' acquired.');render()}
